def init_dirs():
    BASE_DIR.mkdir(parents=True, exist_ok=True)
    FILES_DIR.mkdir(parents=True, exist_ok=True)
    if not STORE_FILE.exists():
        STORE_FILE.write_text("{}", encoding="utf-8")
    if not CONFIG_FILE.exists():
        CONFIG_FILE.write_text("{}", encoding="utf-8")
    # Alten Lock aufräumen
    try:
        if LOCK_FILE.exists() and (time.time() - LOCK_FILE.stat().st_mtime) > 30:
            LOCK_FILE.unlink(missing_ok=True)
    except Exception:
        pass
    log.info(f"Daten-Ordner: {BASE_DIR}")

# ── Datei-Lock für OneDrive-Sicherheit ───────────────────────────────────────
_mem_lock = threading.Lock()

class _FileLock:
    def __init__(self, path, timeout=8.0):
        self.path = path
        self.timeout = timeout
    def __enter__(self):
        deadline = time.time() + self.timeout
        while time.time() < deadline:
            try:
                fd = os.open(str(self.path), os.O_CREAT | os.O_EXCL | os.O_WRONLY)
                os.write(fd, str(os.getpid()).encode())
                os.close(fd)
                return self
            except FileExistsError:
                try:
                    if time.time() - self.path.stat().st_mtime > 15:
                        self.path.unlink(missing_ok=True)
                        continue
                except Exception:
                    pass
                time.sleep(0.08)
        return self
    def __exit__(self, *_):
        try:
            self.path.unlink(missing_ok=True)
        except Exception:
            pass

def _with_store(fn):
    with _mem_lock:
        with _FileLock(LOCK_FILE):
            try:
                raw = STORE_FILE.read_text(encoding="utf-8") if STORE_FILE.exists() else "{}"
                data = json.loads(raw)
            except Exception:
                data = {}
            result = fn(data)
            try:
                tmp = STORE_FILE.with_suffix(".tmp")
                tmp.write_text(json.dumps(data, ensure_ascii=False), encoding="utf-8")
                tmp.replace(STORE_FILE)
            except Exception as e:
                log.error(f"Store-Schreibfehler: {e}")
            return result

def store_get(key):
    return _with_store(lambda d: d.get(key))

def store_set(key, value):
    _with_store(lambda d: d.update({key: value}))
    return True

def store_delete(key):
    _with_store(lambda d: d.pop(key, None))

# ── PDF-Textextraktion (pure Python, keine Bibliothek nötig) ──────────────────
def extract_pdf_pages(path: str) -> list:
    """Extrahiert Text pro Seite aus PDF. Pure Python, keine Bibliothek nötig.
    Gibt zurück: [{page:1, text:"..."}, {page:2, text:"..."}, ...]"""
    try:
        with open(path, 'rb') as f:
            data = f.read()

        # ── Objekt-Offsets aus rohem PDF ermitteln ───────────────────────────
        obj_offsets = {}
        for m in re.finditer(rb'(\d+)\s+0\s+obj', data):
            n = int(m.group(1))
            if n not in obj_offsets:
                obj_offsets[n] = m.start()

        def get_obj(obj_num):
            """Gibt (header_str, stream_bytes_or_None) zurück."""
            off = obj_offsets.get(obj_num)
            if off is None:
                return "", None
            end = data.find(b'endobj', off)
            if end == -1:
                end = min(off + 65536, len(data))
            chunk = data[off:end]
            si = chunk.find(b'stream')
            if si == -1:
                return chunk.decode('latin-1', errors='ignore'), None
            header = chunk[:si].decode('latin-1', errors='ignore')
            raw = chunk[si + 6:]
            if raw[:2] in (b'\r\n', b'\n\r'): raw = raw[2:]
            elif raw[:1] in (b'\r', b'\n'):   raw = raw[1:]
            ei = raw.find(b'endstream')
            if ei != -1:
                raw = raw[:ei]
            if b'FlateDecode' in chunk[:si] or b'/Fl ' in chunk[:si]:
                try:    raw = zlib.decompress(raw)
                except Exception:
                    try: raw = zlib.decompress(raw, -15)
                    except Exception: pass
            return header, raw

        def stream_to_text(raw_bytes: bytes) -> str:
            """Text-Operatoren aus einem PDF-Content-Stream extrahieren."""
            content = raw_bytes.decode('latin-1', errors='ignore')
            texts = []
            for p in re.findall(r'\(([^)\\]*(?:\\.[^)\\]*)*)\)', content):
                p = p.replace('\\n',' ').replace('\\r',' ').replace('\\t',' ')
                p = re.sub(r'\\([0-7]{3})', lambda m: chr(int(m.group(1), 8)), p)
                p = p.replace('\\(','(').replace('\\)',')')
                if len(p.strip()) > 1: texts.append(p.strip())
            for m in re.finditer(r'<([0-9a-fA-F\s]{4,})>\s*(?:Tj|TJ|"|\')', content):
                h = re.sub(r'\s', '', m.group(1))
                try:
                    b = bytes.fromhex(h)
                    d = b.decode('utf-16-be', errors='ignore').strip()
                    if not d or not any(c.isalnum() for c in d):
                        d = b.decode('latin-1', errors='ignore').strip()
                    if len(d) > 1: texts.append(d)
                except Exception: pass
            for arr in re.findall(r'\[([^\]]+)\]\s*TJ', content):
                for p in re.findall(r'\(([^)\\]*(?:\\.[^)\\]*)*)\)', arr):
                    p = p.replace('\\n',' ').replace('\\r',' ').replace('\\t',' ').strip()
                    if len(p) > 1: texts.append(p)
            return ' '.join(texts)

        # ── Page-Objekte finden und Text je Seite extrahieren ────────────────
        pages = []
        for obj_num in sorted(obj_offsets.keys()):
            header, _ = get_obj(obj_num)
            if not re.search(r'/Type\s*/Page[^s]', header):
                continue
            # /Contents N 0 R  oder  /Contents [N 0 R M 0 R ...]
            content_nums = [int(x) for x in re.findall(r'/Contents\s+(\d+)\s+0\s+R', header)]
            arr_m = re.search(r'/Contents\s*\[(.*?)\]', header, re.DOTALL)
            if arr_m:
                content_nums += [int(x) for x in re.findall(r'(\d+)\s+0\s+R', arr_m.group(1))]
            page_parts = []
            for cn in dict.fromkeys(content_nums):  # dedupliziert, Reihenfolge erhalten
                _, cs = get_obj(cn)
                if cs:
                    page_parts.append(stream_to_text(cs))
            text = re.sub(r'\s{3,}', '  ', ' '.join(page_parts)).strip()
            pages.append({"page": len(pages) + 1, "text": text})

        if pages:
            return pages
        # Fallback: gesamten Text als eine Seite
        return [{"page": 1, "text": extract_pdf_text(path)}]
    except Exception as e:
        log.error(f"PDF-Seiten-Extraktion Fehler: {e}")
        return [{"page": 1, "text": extract_pdf_text(path)}]



    """Extrahiert Text aus PDF-Streams: unterstützt FlateDecode, latin-1-(...)- und
    hex-<...>-Strings (CIDFont/UTF-16BE), wie sie moderne Rechnungs-PDFs verwenden."""
    def _decode_hex_str(h):
        """Versucht hex-kodierte PDF-Strings als UTF-16BE oder latin-1 zu dekodieren."""
        h = re.sub(r'\s', '', h)
        if len(h) < 2 or len(h) % 2 != 0:
            return ""
        raw_bytes = bytes.fromhex(h)
        # BOM oder gerade Byteanzahl → UTF-16BE (CIDFont)
        if len(raw_bytes) % 2 == 0:
            try:
                decoded = raw_bytes.decode('utf-16-be', errors='ignore').strip()
                if decoded and any(c.isalnum() or c in ' .,/-' for c in decoded):
                    return decoded
            except Exception:
                pass
        # Fallback: latin-1
        try:
            decoded = raw_bytes.decode('latin-1', errors='ignore').strip()
            if decoded and any(c.isalnum() for c in decoded):
                return decoded
        except Exception:
            pass
        return ""

    try:
        data = open(path, 'rb').read()
        texts = []
        i = 0
        while i < len(data):
            start = data.find(b'stream', i)
            if start == -1: break
            header_start = data.rfind(b'<<', 0, start)
            header = data[header_start:start] if header_start != -1 else b''
            end = data.find(b'endstream', start + 6)
            if end == -1: break
            raw = data[start + 6:end]
            if raw[:2] in (b'\r\n', b'\n\r'): raw = raw[2:]
            elif raw[:1] in (b'\r', b'\n'):   raw = raw[1:]
            if b'FlateDecode' in header or b'/Fl ' in header or b'/Fl\n' in header:
                try: raw = zlib.decompress(raw)
                except:
                    try: raw = zlib.decompress(raw, -15)
                    except: pass
            content = raw.decode('latin-1', errors='ignore')

            # ── Methode 1: Parenthesis-Strings  (text) Tj / TJ ──────────────
            for p in re.findall(r'\(([^)\\]*(?:\\.[^)\\]*)*)\)', content):
                p = p.replace('\\n', ' ').replace('\\r', ' ').replace('\\t', ' ')
                p = re.sub(r'\\([0-7]{3})', lambda m: chr(int(m.group(1), 8)), p)
                p = p.replace('\\(', '(').replace('\\)', ')').replace('\\\\', '\\')
                p = p.strip()
                if len(p) > 1:
                    texts.append(p)

            # ── Methode 2: Hex-Strings  <ABCD...> Tj / TJ ───────────────────
            # Nur nahe bei Tj/TJ-Operatoren, damit keine PDF-Struktur-Hexdaten mitgenommen werden
            for m in re.finditer(r'<([0-9a-fA-F\s]{4,})>\s*(?:Tj|TJ|"|\')', content):
                decoded = _decode_hex_str(m.group(1))
                if len(decoded) > 1:
                    texts.append(decoded)

            # ── Methode 3: TJ-Arrays  [(text1)(text2)] TJ ────────────────────
            for arr in re.findall(r'\[([^\]]+)\]\s*TJ', content):
                for p in re.findall(r'\(([^)\\]*(?:\\.[^)\\]*)*)\)', arr):
                    p = p.replace('\\n', ' ').replace('\\r', ' ').replace('\\t', ' ')
                    p = p.replace('\\(', '(').replace('\\)', ')').replace('\\\\', '\\').strip()
                    if len(p) > 1:
                        texts.append(p)
                for h in re.findall(r'<([0-9a-fA-F\s]{4,})>', arr):
                    decoded = _decode_hex_str(h)
                    if len(decoded) > 1:
                        texts.append(decoded)

            i = end + 9

        result = ' '.join(texts)
        result = re.sub(r'\s{3,}', '  ', result).strip()
        return result
    except Exception as e:
        log.error(f"PDF-Extraktion Fehler: {e}")
        return ""

# ── Ollama-Verwaltung ─────────────────────────────────────────────────────────
_ollama_proc  = None
_pull_lock    = threading.Lock()
_pull_state   = {"running": False, "status": "", "percent": 0, "done": False, "error": ""}

# Sicherstellen dass Ollama beim Programmende immer beendet wird
def _atexit_stop():
    stop_ollama()

atexit.register(_atexit_stop)

def _signal_stop(signum, frame):
    stop_ollama()
    sys.exit(0)

for _sig in (signal.SIGTERM, signal.SIGINT):
    try: signal.signal(_sig, _signal_stop)
    except Exception: pass

def find_ollama():
    p = shutil.which("ollama")
    if p: return p
    candidates = [
        os.path.expandvars(r"%LOCALAPPDATA%\Programs\Ollama\ollama.exe"),
        r"C:\Program Files\Ollama\ollama.exe",
        r"C:\Program Files (x86)\Ollama\ollama.exe",
        "/usr/local/bin/ollama", "/usr/bin/ollama",
        os.path.expanduser("~/.local/bin/ollama"),
    ]
    for c in candidates:
        if os.path.isfile(c): return c
    return None

def is_ollama_running(url=None):
    url = (url or config_get("ollama_url") or "http://localhost:11434").rstrip("/")
    try:
        urllib.request.urlopen(f"{url}/api/tags", timeout=2)
        return True
    except: return False

def stop_ollama():
    """Ollama-Prozess sauber beenden (nur wenn von uns gestartet).
    Beendet den gesamten Prozessbaum – verhindert Zombie-Prozesse auf Windows."""
    global _ollama_proc
    if not (_ollama_proc and _ollama_proc.poll() is None):
        _ollama_proc = None
        return
    pid = _ollama_proc.pid
    try:
        if os.name == "nt":
            # Windows: gesamten Prozessbaum zwangsweise beenden
            subprocess.run(["taskkill", "/F", "/T", "/PID", str(pid)],
                           stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        else:
            # Linux/Mac: Prozessgruppe beenden (Ollama forkt ggf. Kind-Prozesse)
            try:
                import signal as _sig
                os.killpg(os.getpgid(pid), _sig.SIGTERM)
            except Exception:
                _ollama_proc.terminate()
        _ollama_proc.wait(timeout=6)
    except Exception:
        try: _ollama_proc.kill()
        except Exception: pass
    finally:
        _ollama_proc = None

def start_ollama_serve():
    global _ollama_proc
    if is_ollama_running(): return True
    path = find_ollama()
    if not path: return False
    try:
        flags = subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0
        env = os.environ.copy()
        # GPU-Modus aus Konfiguration anwenden
        gpu_mode = config_get("ollama_gpu_mode") or "auto"
        if gpu_mode == "throttled":
            env["OLLAMA_NUM_PARALLEL"] = "1"   # nur 1 parallele Anfrage → weniger GPU-Last
        elif gpu_mode == "cpu":
            env["OLLAMA_NUM_GPU"]      = "0"   # alles auf CPU
            env["OLLAMA_NUM_PARALLEL"] = "1"
        _ollama_proc = subprocess.Popen(
            [path, "serve"],
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
            creationflags=flags, env=env
        )
        for _ in range(30):          # bis zu 15 s warten
            time.sleep(0.5)
            if is_ollama_running(): return True
        return False
    except Exception as e:
        log.error(f"Ollama-Start Fehler: {e}"); return False

def pull_model_bg(model, url, apikey):
    global _pull_state
    with _pull_lock:
        _pull_state = {"running": True, "status": "Starte Download…", "percent": 0, "done": False, "error": ""}
    try:
        payload = json.dumps({"name": model, "stream": True}).encode()
        hdrs = {"Content-Type": "application/json"}
        if apikey: hdrs["Authorization"] = f"Bearer {apikey}"
        req = urllib.request.Request(f"{url.rstrip('/')}/api/pull", data=payload, headers=hdrs)
        with urllib.request.urlopen(req, timeout=7200) as resp:
            for line in resp:
                line = line.strip()
                if not line: continue
                try:
                    d = json.loads(line)
                    status = d.get("status", "")
                    total = d.get("total", 0)
                    completed = d.get("completed", 0)
                    pct = int(completed / total * 100) if total > 0 else 0
                    with _pull_lock:
                        _pull_state["status"]  = status
                        _pull_state["percent"] = pct
                    if status == "success":
                        with _pull_lock: _pull_state.update({"done": True, "running": False, "percent": 100})
                        return
                except: pass
    except Exception as e:
        with _pull_lock: _pull_state.update({"error": str(e)[:200], "running": False})

# ── Config (API-Key etc.) ─────────────────────────────────────────────────────
_cfg_lock = threading.Lock()
CONFIG_LOCK_FILE = BASE_DIR / ".config.lock"

def config_get(key):
    with _cfg_lock:
        with _FileLock(CONFIG_LOCK_FILE):
            try:
                return json.loads(CONFIG_FILE.read_text(encoding="utf-8")).get(key)
            except Exception:
                return None

def config_set(key, value):
    with _cfg_lock:
        with _FileLock(CONFIG_LOCK_FILE):
            try:
                data = json.loads(CONFIG_FILE.read_text(encoding="utf-8")) if CONFIG_FILE.exists() else {}
                data[key] = value
                tmp = CONFIG_FILE.with_suffix(".tmp")
                tmp.write_text(json.dumps(data, ensure_ascii=False), encoding="utf-8")
                tmp.replace(CONFIG_FILE)
            except Exception as e:
                log.error(f"Config-Fehler: {e}")





# ── HTTP Handler ──────────────────────────────────────────────────────────────
class Handler(BaseHTTPRequestHandler):

    def do_GET(self):
        path = self.path.split("?")[0]

        # App HTML
        if path in ("/", "/index.html"):
            body = HTML_CONTENT.encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            # Allow eval() for Babel JSX transformation
            self.send_header("Content-Security-Policy",
                "default-src * 'unsafe-inline' 'unsafe-eval' data: blob:;")
            self.end_headers()
            self.wfile.write(body)

        # Ollama Status
        elif path == "/ollama/status":
            url   = config_get("ollama_url") or "http://localhost:11434"
            model = config_get("ollama_model") or ""
            installed = find_ollama() is not None
            running   = is_ollama_running(url)
            model_ok  = False
            models    = []
            if running:
                try:
                    r2 = urllib.request.urlopen(f"{url.rstrip('/')}/api/tags", timeout=3)
                    d2 = json.loads(r2.read())
                    models = [m["name"] for m in d2.get("models", [])]
                    model_ok = model in models or any(
                        m == model or m.startswith(model.split(":")[0]+":") for m in models)
                except: pass
            self._json(200, {"installed": installed, "running": running,
                             "model_ok": model_ok, "model": model, "models": models}, no_cache=True)

        # Ollama Pull Fortschritt
        elif path == "/ollama/pull/progress":
            with _pull_lock:
                self._json(200, dict(_pull_state), no_cache=True)

        # Key-Value lesen
        elif path.startswith("/data/"):
            key = urllib.parse.unquote(path[6:])
            if not key:
                self._json(400, {"error": "Kein Key"}); return
            val = store_get(key)
            if val is None:
                self.send_response(404); self._cors(); self.end_headers()
            else:
                self._json(200, val)


        # Datei laden
        elif path.startswith("/files/"):
            rest = path[7:]  # e.g. "uuid.pdf" or "uuid.pdf/text"
            if rest.endswith("/pages"):
                # Seitenweise PDF-Text für Seitenauswahl-Modal
                file_id = rest[:-6]
                file_path = FILES_DIR / file_id
                if not file_path.exists():
                    self._json(404, {"error": "Datei nicht gefunden"}); return
                pages = extract_pdf_pages(str(file_path))
                self._json(200, {"pages": pages, "count": len(pages)}, no_cache=True)
            elif rest.endswith("/text"):
                # PDF-Text extrahieren
                file_id = rest[:-5]
                file_path = FILES_DIR / file_id
                if not file_path.exists():
                    self._json(404, {"error": "Datei nicht gefunden"}); return
                text = extract_pdf_text(str(file_path))
                self._json(200, {"text": text, "chars": len(text)}, no_cache=True)
            else:
                file_id = rest
                file_path = FILES_DIR / file_id
                if not file_path.exists() or not file_path.is_file():
                    self.send_response(404); self._cors(); self.end_headers(); return
                mime = mimetypes.guess_type(str(file_path))[0] or "application/octet-stream"
                data = file_path.read_bytes()
                self.send_response(200)
                self.send_header("Content-Type", mime)
                self.send_header("Content-Length", str(len(data)))
                self.send_header("Cache-Control", "max-age=86400")
                self._cors(); self.end_headers(); self.wfile.write(data)

        # Config / Mode lesen
        elif path == "/config/mode":
            if self.command == "GET":
                self._json(200, {
                    "mode":           "ollama",
                    "ollama_model":   config_get("ollama_model") or "",
                    "ollama_url":     config_get("ollama_url") or "http://localhost:11434",
                    "ollama_apikey":  config_get("ollama_apikey") or "",
                    "ollama_gpu_mode": config_get("ollama_gpu_mode") or "auto",
                }, no_cache=True)
            elif self.command == "POST":
                body2 = self.rfile.read(int(self.headers.get("Content-Length",0)))
                data2 = json.loads(body2)
                for k in ("ollama_model","ollama_url","ollama_apikey","ollama_gpu_mode"):
                    if k in data2: config_set(k, data2[k])
                self._json(200, {"ok": True})

        # Ollama Verbindungstest + Modell-Liste
        elif path == "/config/ollama_test":
            url = config_get("ollama_url") or "http://localhost:11434"
            try:
                hdrs = {"User-Agent": "EnergieBerater/1.0"}
                ak = config_get("ollama_apikey")
                if ak: hdrs["Authorization"] = f"Bearer {ak}"
                req = urllib.request.Request(f"{url}/api/tags", headers=hdrs)
                with urllib.request.urlopen(req, timeout=5) as r:
                    data3 = json.loads(r.read())
                models = [m["name"] for m in data3.get("models",[])]
                self._json(200, {"ok": True, "models": models})
            except Exception as e:
                self._json(200, {"ok": False, "error": str(e)})

        else:
            self.send_response(404); self._cors(); self.end_headers()

    def do_OPTIONS(self):
        self.send_response(200); self._cors(); self.end_headers()

    def do_DELETE(self):
        path = self.path.split("?")[0]
        if path.startswith("/data/"):
            key = urllib.parse.unquote(path[6:])
            store_delete(key)
            self._json(200, {"ok": True})
        elif path.startswith("/files/"):
            file_id = path[7:]
            fp = FILES_DIR / file_id
            if fp.exists():
                fp.unlink()
            self._json(200, {"ok": True})
        else:
            self.send_response(404); self._cors(); self.end_headers()

    def do_POST(self):
        path = self.path.split("?")[0]
        length = int(self.headers.get("Content-Length", 0))

        # Key-Value speichern
        if path.startswith("/data/"):
            key = urllib.parse.unquote(path[6:])
            body = self.rfile.read(length)
            try:
                value = json.loads(body)
                store_set(key, value)
                self._json(200, {"ok": True})
            except json.JSONDecodeError as e:
                self._json(400, {"error": f"JSON-Fehler: {e}"})

        # Datei hochladen
        elif path == "/files":
            try:
                content_type = self.headers.get("Content-Type", "application/octet-stream").split(";")[0].strip()
                raw_name = self.headers.get("X-File-Name", "datei.bin")
                orig_name = urllib.parse.unquote(raw_name)
                ext = Path(orig_name).suffix.lower()
                if not ext:
                    ext = {
                        "application/pdf": ".pdf",
                        "image/jpeg": ".jpg", "image/png": ".png", "image/webp": ".webp",
                    }.get(content_type, ".bin")
                file_id = str(uuid.uuid4()) + ext
                data = self.rfile.read(length)
                (FILES_DIR / file_id).write_bytes(data)
                log.info(f"Datei gespeichert: {file_id} ({len(data):,} B) <- {orig_name}")
                self._json(200, {"fileId": file_id, "origName": orig_name, "size": len(data)})
            except Exception as e:
                log.error(f"Datei-Upload Fehler: {e}")
                self._json(500, {"error": f"Upload fehlgeschlagen: {e}"})

        # API Proxy → Ollama
        elif path == "/api":
            body = self.rfile.read(length)
            ollama_model  = config_get("ollama_model")  or ""
            ollama_url    = config_get("ollama_url")    or "http://localhost:11434"
            ollama_apikey = config_get("ollama_apikey") or ""
            try:
                payload = json.loads(body)
                messages = payload.get("messages", [])
                system   = payload.get("system", "")
                ollama_msgs = []
                if system:
                    ollama_msgs.append({"role": "system", "content": system})
                for m in messages:
                    content = m.get("content", "")
                    msg = {"role": m["role"]}
                    if isinstance(content, list):
                        text_parts = [c.get("text","") for c in content if c.get("type")=="text"]
                        img_parts  = [c.get("source",{}).get("data","") for c in content if c.get("type")=="image"]
                        msg["content"] = " ".join(text_parts)
                        if img_parts:
                            msg["images"] = img_parts  # Ollama vision support
                    else:
                        msg["content"] = content
                    ollama_msgs.append(msg)
                ollama_req = {
                    "model":    ollama_model,
                    "messages": ollama_msgs,
                    "stream":   False,
                    "options":  {"num_predict": payload.get("max_tokens", 2000)}
                }
                # think:false deaktiviert qwen3/deepseek-r1 Reasoning-Modus –
                # verhindert dass alle Token für <think> verbraucht werden
                if "think" in payload:
                    ollama_req["think"] = payload["think"]
                ollama_payload = json.dumps(ollama_req).encode()
                ollama_headers = {"Content-Type": "application/json"}
                if ollama_apikey: ollama_headers["Authorization"] = f"Bearer {ollama_apikey}"
                req = urllib.request.Request(
                    f"{ollama_url}/api/chat",
                    data=ollama_payload,
                    headers=ollama_headers)
                with urllib.request.urlopen(req, timeout=300) as resp:
                    resp_data = json.loads(resp.read())
                msg = resp_data.get("message", {})
                # Thinking-Inhalt: neuere Ollama-Versionen → separates "thinking"-Feld
                # Ältere Ollama / inline → <think>...</think> im content-Feld
                text = msg.get("content", "")
                # Abgeschlossene <think>-Blöcke entfernen
                text = re.sub(r'<think>[\s\S]*?</think>', '', text, flags=re.IGNORECASE)
                # Offene <think>-Blöcke entfernen (wenn Token-Limit mitten im Thinking → kein </think>)
                text = re.sub(r'<think>[\s\S]*$', '', text, flags=re.IGNORECASE)
                text = text.strip()
                result = json.dumps({"content": [{"type": "text", "text": text}]}).encode()
                self.send_response(200)
                self.send_header("Content-Type", "application/json")
                self._cors(); self.end_headers(); self.wfile.write(result)
            except urllib.error.HTTPError as e:
                err_body = ""
                try: err_body = e.read().decode("utf-8", errors="replace")
                except: pass
                if e.code == 404:
                    model_hint = f"Modell '{ollama_model}' nicht gefunden. Bitte ausführen: ollama pull {ollama_model}"
                    self._json(503, {"error": {"message": model_hint}})
                else:
                    self._json(503, {"error": {"message": f"Ollama HTTP {e.code}: {err_body[:200]}"}})
            except urllib.error.URLError as e:
                self._json(503, {"error": {"message": f"Ollama nicht erreichbar. Bitte 'ollama serve' starten. ({e.reason})"}})
            except Exception as e:
                log.error(f"Ollama-Fehler: {e}")
                self._json(500, {"error": {"message": str(e)}})

        # Ollama starten
        elif path == "/ollama/start":
            if is_ollama_running():
                self._json(200, {"ok": True, "msg": "Ollama läuft bereits"})
            elif find_ollama() is None:
                self._json(200, {"ok": False, "msg": "Ollama nicht installiert. Bitte von ollama.com herunterladen."})
            else:
                ok = start_ollama_serve()
                self._json(200, {"ok": ok, "msg": "Ollama gestartet" if ok else "Ollama konnte nicht gestartet werden"})

        # Modell herunterladen
        elif path == "/ollama/pull":
            model = config_get("ollama_model") or ""
            url   = config_get("ollama_url") or "http://localhost:11434"
            apikey = config_get("ollama_apikey") or ""
            if not model:
                self._json(400, {"error": "Kein Modell konfiguriert"}); return
            with _pull_lock:
                if _pull_state.get("running"):
                    self._json(200, {"ok": True, "msg": "Download läuft bereits"}); return
            t = threading.Thread(target=pull_model_bg, args=(model, url, apikey), daemon=True)
            t.start()
            self._json(200, {"ok": True, "msg": f"Download gestartet: {model}"})

        # Config speichern
        elif path == "/config/mode":
            body2 = self.rfile.read(int(self.headers.get("Content-Length", 0)))
            try:
                data2 = json.loads(body2)
                for k in ("ollama_model", "ollama_url", "ollama_apikey", "ollama_gpu_mode"):
                    if k in data2:
                        config_set(k, data2[k])
                        log.info(f"Config gespeichert: {k}={data2[k]!r}")
                self._json(200, {"ok": True})
            except Exception as e:
                log.error(f"Config-POST-Fehler: {e}")
                self._json(500, {"error": str(e)})

        else:
            self.send_response(404); self._cors(); self.end_headers()

    def _json(self, code, obj, no_cache=False):
        body = json.dumps(obj, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        if no_cache:
            self.send_header("Cache-Control", "no-store, no-cache, must-revalidate")
            self.send_header("Pragma", "no-cache")
        self._cors(); self.end_headers(); self.wfile.write(body)

    def _cors(self):
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, DELETE, OPTIONS")
        self.send_header("Access-Control-Allow-Headers", "Content-Type, X-Api-Key, X-File-Name")

    def log_message(self, fmt, *args):
        msg = fmt % args
        if "200" not in msg and "OPTIONS" not in msg:
            log.debug(f"HTTP: {msg}")


# ── Eingebettetes HTML ────────────────────────────────────────────────────────

APP_ICON_B64 = ""

_APP_JSX_B64 = ""
import base64 as _base64

# Platzhalter – wird von build_setup.py durch gebundelte HTML (offline) ersetzt
_HTML_B64 = "<!--HTML_B64_PLACEHOLDER-->"

def _build_html_dev():
    """Fallback für direkten Python-Start (python energie_berater_app.py).
    Nutzt CDN – identische Versionen wie build_setup.py."""
    jsx = _base64.b64decode(_APP_JSX_B64).decode("utf-8")
    CDN = "https://cdnjs.cloudflare.com/ajax/libs"
    return "\n".join([
        "<!DOCTYPE html>",
        '<html lang="de"><head>',
        '<meta charset="UTF-8">',
        "<title>EnergieBerater KI</title>",
        f'<script src="{CDN}/react/18.2.0/umd/react.production.min.js"></script>',
        f'<script src="{CDN}/react-dom/18.2.0/umd/react-dom.production.min.js"></script>',
        f'<script src="{CDN}/babel-standalone/7.23.2/babel.min.js"></script>',
        f'<script src="{CDN}/pdf.js/3.11.174/pdf.min.js"></script>',
        "<style>*{box-sizing:border-box;margin:0;padding:0}",
        "html,body,#root{height:100%;overflow:hidden}",
        "body{background:#0e1118}</style>",
        "</head><body>",
        '<div id="root" style="height:100%"></div>',
        '<script type="text/babel" data-presets="react">',
        jsx,
        "</script></body></html>",
    ])

# Patch-Datei neben der EXE hat höchste Priorität (erzeugt von patch.py)
_patch_file = Path(sys.executable).parent / "html_patch.b64" if getattr(sys, "frozen", False) else None
if _patch_file and _patch_file.exists():
    HTML_CONTENT = _base64.b64decode(_patch_file.read_bytes()).decode("utf-8")
elif _HTML_B64.startswith("<!--"):
    HTML_CONTENT = _build_html_dev()
else:
    HTML_CONTENT = _base64.b64decode(_HTML_B64).decode("utf-8")


if __name__ == "__main__":
    try:
        init_dirs()

        # Port finden und Server starten
        port = PORT
        for _ in range(10):
            try:
                srv = ThreadingHTTPServer(("localhost", port), Handler)  # Thread pro Request → kein Blocking
                break
            except OSError:
                port += 1

        url = f"http://localhost:{port}"
        threading.Thread(target=srv.serve_forever, daemon=True).start()
        time.sleep(0.4)
        log.info(f"Server: {url}  Daten: {BASE_DIR}")

        # PyQt6 Desktop-Fenster
        from PyQt6.QtWidgets import QApplication, QMainWindow
        from PyQt6.QtWebEngineWidgets import QWebEngineView
        from PyQt6.QtWebEngineCore import QWebEngineProfile, QWebEngineSettings, QWebEnginePage
        from PyQt6.QtCore import QUrl

        qt = QApplication(sys.argv)
        qt.setApplicationName("EnergieBerater KI")

        profile = QWebEngineProfile("EnergieBerater", qt)
        profile.setPersistentStoragePath(str(BASE_DIR / "qt_storage"))
        profile.setCachePath(str(BASE_DIR / "qt_cache"))
        s = profile.settings()
        for attr in [
            QWebEngineSettings.WebAttribute.LocalStorageEnabled,
            QWebEngineSettings.WebAttribute.JavascriptEnabled,
            QWebEngineSettings.WebAttribute.LocalContentCanAccessRemoteUrls,
            QWebEngineSettings.WebAttribute.AllowRunningInsecureContent,
            QWebEngineSettings.WebAttribute.JavascriptCanOpenWindows,
            QWebEngineSettings.WebAttribute.JavascriptCanAccessClipboard,
        ]:
            try:
                s.setAttribute(attr, True)
            except Exception:
                pass
        # Chromium flags: allow eval, disable web security for localhost
        os.environ.setdefault("QTWEBENGINE_CHROMIUM_FLAGS",
            "--disable-web-security --allow-running-insecure-content "
            "--disable-features=BlockInsecurePrivateNetworkRequests")

        _cleaned = [False]

        class DebugPage(QWebEnginePage):
            def javaScriptConsoleMessage(self, level, message, line, source):
                log.info(f"JS [{level.name}] {source}:{line}: {message}")

        class MainWindow(QMainWindow):
            def closeEvent(self, event):
                if not _cleaned[0]:
                    _cleaned[0] = True
                    try:
                        view.stop()
                        view.setPage(None)
                        page.deleteLater()
                        view.deleteLater()
                        profile.deleteLater()
                    except Exception:
                        pass
                    stop_ollama()   # Ollama beenden (falls von uns gestartet)
                event.accept()
                qt.quit()

        win = MainWindow()
        win.setWindowTitle("EnergieBerater KI")
        win.resize(1440, 920)
        win.setMinimumSize(960, 640)
        # Icon setzen falls vorhanden
        try:
            from PyQt6.QtGui import QIcon
            import base64, tempfile
            icon_data = base64.b64decode(APP_ICON_B64)
            tmp_ico = Path(tempfile.mktemp(suffix=".ico"))
            tmp_ico.write_bytes(icon_data)
            win.setWindowIcon(QIcon(str(tmp_ico)))
            qt.setWindowIcon(QIcon(str(tmp_ico)))
        except Exception as e:
            log.warning(f"Icon konnte nicht gesetzt werden: {e}")

        page = DebugPage(profile, win)
        view = QWebEngineView(win)
        view.setPage(page)
        win.setCentralWidget(view)
        win.show()
        page.load(QUrl(url + "/"))

        qt.exec()
        stop_ollama()   # Sicherheits-Fallback: os._exit() umgeht finally
        try: srv.shutdown()
        except Exception: pass
        os._exit(0)

    except Exception as e:
        log.error(f"Fehler: {e}")
        import traceback; log.error(traceback.format_exc())
        try:
            import ctypes
            ctypes.windll.user32.MessageBoxW(0,
                f"Fehler beim Starten:\n\n{e}\n\nLog: {LOG_FILE}",
                "EnergieBerater KI", 0x10)
        except Exception:
            input(f"Fehler: {e}\nEnter...")
    finally:
        try: srv.shutdown()
        except Exception: pass
        if _ollama_proc and _ollama_proc.poll() is None:
            try: _ollama_proc.terminate()
            except Exception: pass
